{
  "research_concepts": [
    "teammate drive",
    "pick and roll (PNR)",
    "points per possession (PPP)",
    "possession-level sequence",
    "preceding action",
    "play-type labeling accuracy",
    "NBA play-by-play",
    "within-possession action ordering"
  ],
  "methodological_questions": [
    "Can play-by-play reliably identify a teammate drive preceding a pick-and-roll within the same possession?",
    "Does play-type labeling introduce bias when linking a preceding action to the PNR outcome?",
    "Is the co-occurrence of a teammate drive and a subsequent PNR frequent enough for adequate power?",
    "Will lookahead leakage contaminate the DRIVE and PNR labels?",
    "What is the causal identification strategy for the effect of a preceding action on subsequent PPP?"
  ],
  "historical_evidence": [
    {
      "id": "FAM:SF-APPM-014",
      "status_as_recorded": "not a hypothesis test",
      "finding": "Play-type label audit overall FAIL: DRIVE foul-draw 1.7% vs 14-22% benchmark; most PTs PPP above benchmark band; MIA identity checks fail; 40.8% low confidence."
    },
    {
      "id": "FAM:SF-PAP-096",
      "status_as_recorded": "artifact",
      "finding": "SPOT_UP 2.83 PPP (100% makes) and TRANSITION 0.62 PPP because assisted flag exists only on makes; after rewrite SPOT_UP ~1.16, TRANSITION ~1.20."
    },
    {
      "id": "FAM:SF-CHT-025",
      "status_as_recorded": "artifact",
      "finding": "OTHER: 36% end in fouls, PPP inflated. DRIVE: 12pp below foul benchmark. PNR shows 22% foul rate. Only 0.7% of possessions map to a real play type via initiation_type."
    },
    {
      "id": "FAM:SF-APPM-058",
      "status_as_recorded": "not a hypothesis test",
      "finding": "2024-25 shot-level PNR share of half-court shots ranges from 7.6% (OKC) to 13.8% (IND); no pass/fail gate, rates used as calibration input."
    },
    {
      "id": "FAM:SF-APPS-010",
      "status_as_recorded": "inconclusive",
      "finding": "DRIVE PPP 0.889 → 0.949 (+0.060); PNR +0.087; PULL_UP -0.077 across playoff series buckets; no clear signal, observational with selection caveats."
    },
    {
      "id": "FAM:SF-APPA-030",
      "status_as_recorded": "inconclusive",
      "finding": "Backfilled play-type label verification FAIL: PNR 28.7% (exceeds 20-28% band); PULL_UP 7.9% fail; 3100 games with team PNR >33% fail; team identity fail; final FAIL."
    },
    {
      "id": "FAM:SF-APPS-058",
      "status_as_recorded": "untestable",
      "finding": "On-ball defensive scheme labels (ORL-DET G1): DET label rate 14.9% (n=10), ORL 3.3% (n=2); switches_on unpopulated."
    },
    {
      "id": "FAM:SF-APPS-011",
      "status_as_recorded": "supported",
      "finding": "DRIVE RS PPP 1.198 vs PO 0.912 (-0.286) across 25 teams; motivated playoff DRIVE exclusion and proposed DSI offset."
    },
    {
      "id": "FAM:SF-CHT-028",
      "status_as_recorded": "untestable",
      "finding": "action_sequences CV=0.612, stability CV=0.919 (unstable); average sample per key 6.9; locked 9-pattern set with clutch_performance r(win)=+0.38."
    },
    {
      "id": "FAM:SF-APPA-050",
      "status_as_recorded": "not a hypothesis test",
      "finding": "Superstar sequential suppression: opponent play before the star. PUTBACK is top suppressor for 6+ stars (e.g. D. Mitchell 1.178 → 0.884, n_after=95); no multiplicity correction."
    }
  ],
  "failed_approaches": [
    {
      "id": "FAM:SF-APPM-014",
      "what_failed": "relying on inferred play-type labels (DRIVE, PNR) for PPP analysis without thorough audit",
      "why": "labels had systematic foul leakage, high OTHER share, and identity-check failures; classification error and leakage rendered the labels unreliable."
    },
    {
      "id": "FAM:SF-PAP-096",
      "what_failed": "using raw play-type labels for PPP comparison",
      "why": "the possession-level play-type classifier used an assisted flag that existed only on made shots, causing SPOT_UP to reach 2.83 PPP and TRANSITION 0.62 PPP; outcome contamination produced a severe artifact."
    },
    {
      "id": "FAM:SF-CHT-025",
      "what_failed": "treating play-type PPP differences as real efficiency rather than labeling artifacts",
      "why": "DRIVE foul draw was 12pp below benchmark, OTHER had 36% foul endings and inflated PPP, PNR 22% foul rate, and only 0.7% of possessions were mapped to a real play type via initiation_type."
    },
    {
      "id": "FAM:SF-APPA-030",
      "what_failed": "backfilling play-type labels for use at scale",
      "why": "backfilled labels failed team-identity and distribution benchmarks; 82.8% of PNR labels were proxy-calibrated, and PULL_UP shares were 0-2% for many teams, revealing systematic misclassification."
    },
    {
      "id": "FAM:SF-APPS-058",
      "what_failed": "attempting to label on-ball defensive schemes from NBA matchup/PBP fields",
      "why": "label rates were 14.9% and 3.3%, and the switches_on feed never populated; severe label sparsity made the labels unusable."
    },
    {
      "id": "FAM:SF-CHT-028",
      "what_failed": "using action_sequences as a stable tactical signal",
      "why": "action_sequences exhibited instability (CV=0.919) and tautological keys, with an average sample of only 6.9 per key; the signal was too noisy and sparse for reliable use."
    }
  ],
  "evidence_establishes": [
    "DRIVE and PNR labels from the current pipeline are systematically compromised by foul leakage, inflated PPP, and misclassification.",
    "Outcome-dependent features (assisted flag on made shots) leak into play-type labels, producing large artifacts in PPP estimates.",
    "Only 0.7% of possessions map to a real play type via the initiation_type field, indicating coarse labeling and limited within-possession sequence discrimination.",
    "action_sequences derived from the pipeline are unstable (CV=0.919) and sparse, making reliable identification of a specific DRIVE-then-PNR pattern very unlikely.",
    "Backfilled play-type labels fail team-identity and frequency benchmarks, even for high-level types like PNR and PULL_UP."
  ],
  "evidence_does_not_establish": [
    "Whether a genuine effect of a teammate drive preceding a PNR on PNR PPP exists after correcting the labeling issues.",
    "The actual frequency of possessions containing both a teammate drive and a subsequent PNR.",
    "Whether a re-engineered play-type labeling system could detect such an effect.",
    "The magnitude or direction of any causal relationship between preceding teammate drive and PNR efficiency."
  ],
  "own_inferences": [
    "Given the severe labeling artifacts documented across multiple audits, any naïve comparison of PNR PPP with and without a preceding teammate drive would almost certainly be contaminated by misclassification and outcome leakage.",
    "The joint event ‘teammate drive followed by PNR within the same possession’ is likely very rare, leading to severe power limitations and an inflated risk of spurious findings from small, selected subsamples.",
    "Addressing the question would require a complete rebuild of the play-type labeling pipeline, including correction of foul leakage, removal of lookahead bias, and validation against external tracking data, before any test could be credible."
  ],
  "uncertainties": [
    "The exact base rate of possessions with a teammate drive followed by a PNR is unknown, but evidence of label coarseness (0.7% initiation_type mapping) suggests it is extremely low.",
    "It is unclear whether future iterations of the labeling system could reduce misclassification enough to make the hypothesis testable.",
    "The role of defensive scheme, lineup quality, and game context as confounders has not been evaluated for this specific sequence."
  ],
  "historical_effect": {
    "changed_decision": "yes",
    "explanation": "Before the historical retrieval, it might have been assumed that the existing DRIVE and PNR labels were sufficiently accurate to test a within-possession sequential effect. The retrieved records, especially the play-type label audits (FAM:SF-APPM-014, FAM:SF-CHT-025, FAM:SF-PAP-096, FAM:SF-APPA-030) and the action_sequences instability (FAM:SF-CHT-028), reveal systematic label error, outcome leakage, and sparsity that render the current data unfit for this question. This evidence changed the decision from a possible ‘proceed’ to a clear ‘do_not_proceed’ because the risk of an artifact-driven result is overwhelmingly high."
  },
  "testability": {
    "p_testable": 0.15,
    "blocking_constraints": [
      {
        "code": "LABEL_ERROR",
        "text": "DRIVE and PNR labels are contaminated by foul leakage and misclassification, making it impossible to reliably isolate a teammate drive or the subsequent PNR in the same possession."
      },
      {
        "code": "LEAKAGE_LOOKAHEAD",
        "text": "Play-type labels are inferred after the possession outcome; the assisted-flag leak shows that outcome knowledge can corrupt the labeling, so a preceding drive label may be influenced by the eventual PNR outcome."
      },
      {
        "code": "SAMPLE_SIZE_POWER",
        "text": "The co-occurrence of a teammate drive and a later PNR within the same possession is expected to be extremely rare (likely far below the several thousand events needed for adequate power), and the sparsity observed in action_sequences supports this concern."
      },
      {
        "code": "EXPOSURE_SPARSITY",
        "text": "Even if some instances exist, the low base rate means that the “treated” group will be very small, leading to volatile estimates and high sensitivity to outliers."
      },
      {
        "code": "CONFOUNDING",
        "text": "Game situation, defensive scheme, shot clock, and lineup quality could all influence both the decision to drive and the success of a later PNR, and with limited sample it would be difficult to control for them."
      }
    ]
  },
  "prior_work": {
    "already_answered": "no",
    "cited": [
      "FAM:SF-APPM-014",
      "FAM:SF-PAP-096",
      "FAM:SF-CHT-025",
      "FAM:SF-APPA-030",
      "FAM:SF-APPM-058",
      "FAM:SF-APPS-058",
      "FAM:SF-CHT-028",
      "FAM:SF-APPA-050"
    ],
    "summary": "No earlier study tested the effect of a preceding teammate drive on PNR PPP. The closest work (superstar sequential suppression, FAM:SF-APPA-050) examined across-possession opponent actions and suffered from small cell sizes and no multiplicity correction, illustrating the methodological challenges for such sequence-based hypotheses. The dominant signal from prior work is that the current play-type labeling pipeline is not trustworthy for this kind of fine-grained, within-possession question."
  },
  "risks": [
    {
      "code": "LABEL_ERROR",
      "text": "DRIVE and PNR play types exhibit systematic foul leakage, inflated PPP, and team-identity failures; any effect found would likely be a labeling artifact."
    },
    {
      "code": "LEAKAGE_LOOKAHEAD",
      "text": "Outcome information (makes, fouls) leaks into the play-type inference, so a preceding DRIVE label could be influenced by the subsequent PNR result, creating a spurious correlation."
    },
    {
      "code": "SAMPLE_SIZE_POWER",
      "text": "The number of possessions containing a teammate drive followed by a PNR is expected to be very small, rendering the test underpowered for realistic effect sizes."
    },
    {
      "code": "EXPOSURE_SPARSITY",
      "text": "The rarity of the combined event hampers reliable estimation and makes the analysis vulnerable to a few extreme possessions."
    },
    {
      "code": "CONFOUNDING",
      "text": "Differences in game context, defensive alignment, and team quality could confound the relationship between a drive preceding a PNR and PNR efficiency."
    },
    {
      "code": "MULTIPLE_TESTING",
      "text": "If the analysis explores multiple preceding play types (not just DRIVE), the risk of false positives increases without explicit correction."
    },
    {
      "code": "RTM_SELECTION",
      "text": "Conditioning on possessions that contain both a drive and a PNR may select for atypical sequences, introducing selection bias that mimics an effect."
    }
  ],
  "predicted_outcome": {
    "supported": 0.05,
    "rejected": 0.05,
    "untestable": 0.70,
    "artifact": 0.15,
    "uncertain": 0.05
  },
  "decision": "do_not_proceed",
  "design": {
    "estimand": "Causal effect of a teammate drive occurring before a pick-and-roll within the same possession on the points-per-possession of that pick-and-roll, measured as the difference in mean PPP between PNR possessions that feature a preceding teammate drive and those that do not, after controlling for confounders.",
    "unit": "Individual possession with a labeled pick-and-roll.",
    "sample": "All possessions from the 2022-23 through 2025-26 regular season and playoffs in which a PNR is identified and a prior drive by a different player (teammate) is recorded earlier in the same possession, provided the drive did not result in a shot attempt, drawn foul, or turnover. Only possessions with high-confidence labels (post-correction) are included. A control group of PNR possessions without any preceding teammate drive is matched or regression-adjusted.",
    "power": "Minimum detectable effect of 0.02 PPP (baseline PNR PPP ~0.95, SD ~1.2) with 80% power at α=0.05 requires approximately 5,000 PNR+drive possessions in a two-sample comparison. Feasibility must be reassessed after label correction; current label audits suggest the required sample is not achievable.",
    "controls": "Game margin, period, seconds remaining on shot clock, possession start type (e.g., off defensive rebound), location (home/away), on-court lineup net rating (as a proxy for lineup quality), and opponent defensive rating.",
    "falsification": "1) Test that a preceding drive by the same player (i.e., the PNR ball-handler driving before the PNR) does not raise PNR PPP. 2) Test that a preceding drive in the opponent’s prior possession (irrelevant drive) has no effect. 3) Replace DRIVE with another common preceding action (e.g., OFF_SCREEN) and verify that no spurious effect is found.",
    "multiplicity": "If multiple preceding play types are tested, apply Bonferroni correction for the number of types (e.g., DRIVE, POST_UP, CUT). The primary test should be pre-registered for DRIVE only.",
    "decision_rule": "Reject the null hypothesis of no effect if the adjusted p-value is <0.05, the estimated effect size is at least +0.02 PPP, and the falsification tests do not show a similar effect for the control comparisons.",
    "data_version": "Play-type labels must be rebuilt to correct the known artifacts: foul leakage (SF-APPM-014, SF-CHT-025), assisted-flag contamination (SF-PAP-096), and backfill misclassification (SF-APPA-030). The corrected labels must pass a new audit against external benchmarks before this test is run."
  }
}

